import { createResource, zodResolver } from 'qortex-resource';
import { z } from 'zod';

const User = z.object({
  name: z.string().min(1),
  email: z.string().email(),
});

const user = createResource({
  key: ['user', userId],
  validate: { resolver: zodResolver(User), on: 'blur' },
  persist: { draft: true },
  mutation: { optimistic: true },
  source: {
    fetch: () => api.getUser(userId),
    save: (draft) => api.updateUser(userId, draft),
  },
  onSaveSuccess: () => console.log('saved'),
  onSaveError: (e) => console.error(e),
});

user.set('name', 'Ada');
user.array('tags').append('admin');

const city = user.field('profile.address.city');
city.set('London');
await city.validate();

const {
  draft, data, isChanged, isValid, errors,
  isLoading, isSaving, mutation,
} = user.snapshot;
